/**
 * Error types raised by Server Actions that are *expected* failures rather
 * than bugs. Each one carries the `ErrorCode` that `toAppError()` maps into
 * the `AppErrorShape` the client form layer renders, mirroring the convention
 * already used by `PermissionDeniedError` and `TenantScopeError`.
 *
 * These live in `src/actions/_lib` because only the action layer produces
 * them — services throw their own domain errors, and repositories throw none.
 */

import type { LimitedResource } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";
import type { PermissionAction } from "@/types/permission";

/** No session at all, or a session whose active organization is gone. */
export class UnauthorizedActionError extends Error {
  readonly code = "unauthorized" as const;

  constructor(message = "Sign in to continue.") {
    super(message);
    this.name = "UnauthorizedActionError";
  }
}

/**
 * `can()` returned false. Distinct from `PermissionDeniedError` (thrown by
 * `assertCan()` inside services) only in that the action layer already knows
 * the action name and does not need the full `PermissionDecision`.
 */
export class ForbiddenActionError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly action: PermissionAction) {
    super(`Permission denied: ${action}`);
    this.name = "ForbiddenActionError";
  }
}

/** A plan quota from `@/config/plan-limits` would be breached. */
export class PlanLimitError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly resource: LimitedResource,
    readonly limit: number,
    readonly used: number,
  ) {
    super(`Plan limit reached for ${resource}: ${used}/${limit}`);
    this.name = "PlanLimitError";
  }
}

/** The token bucket in `@/lib/rate-limit` refused the request. */
export class RateLimitedError extends Error {
  readonly code = "rate_limited" as const;

  constructor(
    readonly bucketKey: string,
    readonly resetAt: IsoTimestamp,
  ) {
    super(`Rate limit exceeded for ${bucketKey}; retry after ${resetAt}`);
    this.name = "RateLimitedError";
  }
}

/** A feature flag that gates the whole action is off for this organization. */
export class FeatureUnavailableError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly flag: string) {
    super(`Feature not available: ${flag}`);
    this.name = "FeatureUnavailableError";
  }
}

/** The row the action addresses does not exist inside the actor's tenant. */
export class ActionNotFoundError extends Error {
  readonly code = "not_found" as const;

  constructor(readonly what: string) {
    super(`Not found: ${what}`);
    this.name = "ActionNotFoundError";
  }
}
/**
 * Maps thrown domain errors onto `AppErrorShape`.
 *
 * The service layer throws (`PermissionDeniedError`, `TenantScopeError`,
 * `FeatureDisabledError`, `AlreadyArchivedError`, `InvalidSlugError`,
 * `ZodError`); Server Actions and Route Handlers never propagate those to the
 * client. Everything funnels through `toAppError()` so one thrown class maps
 * to exactly one `ErrorCode` and one HTTP status, app-wide.
 */
import { FeatureDisabledError } from "@/lib/feature-flags";
import { PermissionDeniedError } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import type { ActionResult, AppErrorShape, ErrorCode } from "@/types/api";
import { ZodError, type ZodIssue } from "zod";

export const HTTP_STATUS_BY_CODE: Readonly<Record<ErrorCode, number>> = {
  unauthorized: 401,
  forbidden: 403,
  not_found: 404,
  validation_failed: 422,
  conflict: 409,
  rate_limited: 429,
  plan_limit_exceeded: 402,
  tenant_scope_violation: 403,
  internal_error: 500,
};

/** True for the error classes this module knows how to translate faithfully. */
export function isDomainError(error: unknown): boolean {
  return (
    error instanceof PermissionDeniedError ||
    error instanceof TenantScopeError ||
    error instanceof FeatureDisabledError ||
    error instanceof AlreadyArchivedError ||
    error instanceof InvalidSlugError ||
    error instanceof ZodError
  );
}

/** Collapses a `ZodError` into the `field → messages` map forms consume. */
export function fieldErrorsFromZod(
  error: ZodError,
): Readonly<Record<string, readonly string[]>> {
  const fields: Record<string, string[]> = {};
  for (const issue of error.issues as readonly ZodIssue[]) {
    const key = issue.path.length === 0 ? "_root" : issue.path.join(".");
    (fields[key] ??= []).push(issue.message);
  }
  return fields;
}

export function toAppError(error: unknown): AppErrorShape {
  if (error instanceof ZodError) {
    return {
      code: "validation_failed",
      message: "Please correct the highlighted fields.",
      fieldErrors: fieldErrorsFromZod(error),
    };
  }

  if (error instanceof PermissionDeniedError) {
    return {
      code: "forbidden",
      message: error.message,
      meta: {
        action: error.action,
        resourceKind: error.decision.resourceKind,
        reason: error.decision.reason,
      },
    };
  }

  if (error instanceof TenantScopeError) {
    return {
      code: "tenant_scope_violation",
      message: "That resource belongs to a different organization.",
      meta: { expectedOrgId: error.expectedOrgId, actualOrgId: error.actualOrgId },
    };
  }

  if (error instanceof FeatureDisabledError) {
    return {
      code: "forbidden",
      message: error.message,
      meta: { flag: error.flag },
    };
  }

  if (error instanceof AlreadyArchivedError) {
    return {
      code: "conflict",
      message: error.message,
      meta: { entity: error.entity, id: error.id },
    };
  }

  if (error instanceof InvalidSlugError) {
    return {
      code: "validation_failed",
      message: error.message,
      fieldErrors: { slug: [error.message] },
      meta: { value: error.value },
    };
  }

  return {
    code: "internal_error",
    message:
      error instanceof Error ? error.message : "Something went wrong. Try again.",
  };
}

/** The failure envelope a Server Action returns instead of throwing. */
export function toActionResult(error: unknown): ActionResult<never> {
  return {
    ok: false,
    error: toAppError(error),
    submittedAt: new Date().toISOString(),
  };
}
/**
 * Primitive identifier and envelope types shared by every Taskflow domain type.
 *
 * Every entity in Taskflow uses opaque branded string ids so that an `IssueId`
 * can never be silently passed where a `ProjectId` is expected. Ids are ULID
 * strings at runtime; the brand exists only at the type level.
 */

declare const brand: unique symbol;

/** Attaches a compile-time-only tag to a primitive type. */
export type Branded<T, B extends string> = T & { readonly [brand]: B };

export type UserId = Branded<string, "UserId">;
export type OrgId = Branded<string, "OrgId">;
export type ProjectId = Branded<string, "ProjectId">;
export type IssueId = Branded<string, "IssueId">;
export type CommentId = Branded<string, "CommentId">;
export type MemberId = Branded<string, "MemberId">;
export type NotificationId = Branded<string, "NotificationId">;
export type ActivityId = Branded<string, "ActivityId">;
export type InvitationId = Branded<string, "InvitationId">;
export type LabelId = Branded<string, "LabelId">;
export type AttachmentId = Branded<string, "AttachmentId">;
export type SubscriptionId = Branded<string, "SubscriptionId">;
export type SessionId = Branded<string, "SessionId">;
export type WebhookId = Branded<string, "WebhookId">;

/** Union of every branded id used in the app, for generic id helpers. */
export type AnyId =
  | UserId
  | OrgId
  | ProjectId
  | IssueId
  | CommentId
  | MemberId
  | NotificationId
  | ActivityId
  | InvitationId
  | LabelId
  | AttachmentId
  | SubscriptionId
  | SessionId
  | WebhookId;

/** ISO-8601 timestamp string as stored in SQLite text columns. */
export type IsoTimestamp = Branded<string, "IsoTimestamp">;

/** Rows carrying the standard created/updated bookkeeping columns. */
export interface Timestamps {
  readonly createdAt: IsoTimestamp;
  readonly updatedAt: IsoTimestamp;
}

/**
 * Soft-delete marker. `archivedAt === null` means the row is live. Repositories
 * must filter on this via the helpers in `src/lib/soft-delete.ts` rather than
 * writing the predicate by hand.
 */
export interface SoftDeletable {
  readonly archivedAt: IsoTimestamp | null;
}

/** Rows that belong to exactly one tenant. Enforced by `src/lib/tenant.ts`. */
export interface TenantScoped {
  readonly orgId: OrgId;
}

export type SortDirection = "asc" | "desc";

export interface SortSpec<TField extends string = string> {
  readonly field: TField;
  readonly direction: SortDirection;
}

/** Cursor pagination request shared by every repository `list*` method. */
export interface PageRequest {
  readonly limit: number;
  readonly cursor?: string | null;
}

/** Cursor pagination response shared by every repository `list*` method. */
export interface Page<T> {
  readonly items: readonly T[];
  readonly nextCursor: string | null;
  readonly total: number;
}

/** Options accepted by every soft-delete-aware repository read. */
export interface ArchiveScope {
  readonly includeArchived?: boolean;
}

export function makePage<T>(
  items: readonly T[],
  nextCursor: string | null,
  total: number,
): Page<T> {
  return { items, nextCursor, total };
}

export function toIsoTimestamp(value: Date | string): IsoTimestamp {
  const date = typeof value === "string" ? new Date(value) : value;
  return date.toISOString() as IsoTimestamp;
}
/** Token-bucket refill and exhaustion. */
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { getPlanLimits } from "@/config/plan-limits";
import {
  RATE_LIMIT_BUCKETS,
  consumeRateLimit,
  getBucketConfig,
  resetRateLimits,
  setOrgPlan,
} from "@/lib/rate-limit";
import { ORG_A, ORG_B } from "../helpers/factories";

beforeEach(() => {
  resetRateLimits();
  vi.useFakeTimers();
  vi.setSystemTime(new Date("2026-03-15T12:00:00.000Z"));
});

afterEach(() => {
  vi.useRealTimers();
});

describe("lib/rate-limit", () => {
  it("returns the declared config for a known bucket", () => {
    expect(getBucketConfig("member:invite")).toEqual(
      RATE_LIMIT_BUCKETS["member:invite"],
    );
  });

  it("falls back to a default config for an unknown bucket", () => {
    const config = getBucketConfig("something:new");
    expect(config.capacity).toBeGreaterThan(0);
    expect(config.refillPerMinute).toBeGreaterThan(0);
  });

  it("allows a first request and reports the remaining tokens", async () => {
    const verdict = await consumeRateLimit(ORG_A, "member:invite");
    expect(verdict.allowed).toBe(true);
    expect(verdict.remaining).toBe(19);
  });

  it("exhausts the bucket and then refuses", async () => {
    const capacity = getBucketConfig("auth:password-reset").capacity;
    for (let i = 0; i < capacity; i += 1) {
      expect((await consumeRateLimit(ORG_A, "auth:password-reset")).allowed).toBe(true);
    }

    const denied = await consumeRateLimit(ORG_A, "auth:password-reset");
    expect(denied.allowed).toBe(false);
    expect(denied.remaining).toBe(0);
  });

  it("refills over time at the declared rate", async () => {
    const { capacity, refillPerMinute } = getBucketConfig("auth:password-reset");
    for (let i = 0; i < capacity; i += 1) {
      await consumeRateLimit(ORG_A, "auth:password-reset");
    }
    expect((await consumeRateLimit(ORG_A, "auth:password-reset")).allowed).toBe(false);

    vi.advanceTimersByTime(2 * 60_000);
    const after = await consumeRateLimit(ORG_A, "auth:password-reset");
    expect(after.allowed).toBe(true);
    expect(after.remaining).toBe(2 * refillPerMinute - 1);
  });

  it("never refills past capacity", async () => {
    await consumeRateLimit(ORG_A, "member:invite");
    vi.advanceTimersByTime(24 * 60 * 60_000);

    const verdict = await consumeRateLimit(ORG_A, "member:invite");
    expect(verdict.remaining).toBe(getBucketConfig("member:invite").capacity - 1);
  });

  it("charges the supplied cost", async () => {
    const verdict = await consumeRateLimit(ORG_A, "member:invite", 5);
    expect(verdict.allowed).toBe(true);
    expect(verdict.remaining).toBe(15);
  });

  it("refuses a cost larger than the bucket without spending tokens", async () => {
    const denied = await consumeRateLimit(ORG_A, "auth:password-reset", 999);
    expect(denied.allowed).toBe(false);
    expect(denied.remaining).toBe(getBucketConfig("auth:password-reset").capacity);
  });

  it("keeps buckets separate per org and per key", async () => {
    const capacity = getBucketConfig("auth:password-reset").capacity;
    for (let i = 0; i < capacity; i += 1) {
      await consumeRateLimit(ORG_A, "auth:password-reset");
    }

    expect((await consumeRateLimit(ORG_A, "auth:password-reset")).allowed).toBe(false);
    expect((await consumeRateLimit(ORG_B, "auth:password-reset")).allowed).toBe(true);
    expect((await consumeRateLimit(ORG_A, "member:invite")).allowed).toBe(true);
  });

  it("scales capacity with the org's plan quota rather than hard-coding it", async () => {
    setOrgPlan(ORG_B, "growth");
    const growth = await consumeRateLimit(ORG_B, "member:invite");
    const free = await consumeRateLimit(ORG_A, "member:invite");

    expect(getPlanLimits("growth").apiRequestsPerHour).toBeGreaterThan(
      getPlanLimits("free").apiRequestsPerHour,
    );
    expect(growth.remaining).toBeGreaterThan(free.remaining);
  });

  it("reports a resetAt in the future when the bucket is empty", async () => {
    const capacity = getBucketConfig("auth:password-reset").capacity;
    for (let i = 0; i < capacity; i += 1) {
      await consumeRateLimit(ORG_A, "auth:password-reset");
    }

    const denied = await consumeRateLimit(ORG_A, "auth:password-reset");
    expect(new Date(denied.resetAt).getTime()).toBeGreaterThan(Date.now());
  });
});

"use server";

/**
 * Signs a user in and sets the session cookie.
 *
 * Owner D. Runs before any tenant is known, so it cannot go through
 * `withAction()` — there is no `Actor` to resolve yet. The rate limit is
 * charged against the anonymous bucket to blunt credential stuffing.
 *
 * Must call (do not reimplement): loginSchema, setSessionCookie,
 * consumeRateLimit
 */

import { ANONYMOUS_ORG_ID } from "@/actions/_lib/permission-resources";
import { RateLimitedError } from "@/actions/_lib/action-errors";
import { toActionResult } from "@/lib/errors";
import { consumeRateLimit } from "@/lib/rate-limit";
import { setSessionCookie } from "@/lib/session";
import { loginSchema } from "@/schemas/auth";
import { login } from "@/server/services/auth-service";
import { resolveSession } from "@/server/services/session-service";
import { UnauthorizedActionError } from "@/actions/_lib/action-errors";
import type { ActionResult } from "@/types/api";
import type { SessionPrincipal } from "@/types/member";

const LOGIN_BUCKET = "auth:login";

export async function loginAction(raw: unknown): Promise<ActionResult<SessionPrincipal>> {
  const parsed = loginSchema.safeParse(raw);
  if (!parsed.success) {
    return toActionResult(parsed.error);
  }

  try {
    const verdict = await consumeRateLimit(ANONYMOUS_ORG_ID, LOGIN_BUCKET);
    if (!verdict.allowed) {
      throw new RateLimitedError(LOGIN_BUCKET, verdict.resetAt);
    }

    const { token } = await login(parsed.data);
    const principal = await resolveSession(token);
    if (principal === null) {
      throw new UnauthorizedActionError("That sign-in could not be completed.");
    }

    await setSessionCookie(token, principal.expiresAt);
    return { ok: true, data: principal, submittedAt: new Date().toISOString() };
  } catch (error) {
    return toActionResult(error);
  }
}
"use server";

/**
 * Requests and confirms a password reset.
 *
 * Owner D. The request half deliberately reports success even for an unknown
 * address so the form cannot be used to enumerate accounts; the rate limit is
 * what stops it being abused as a mail cannon.
 *
 * Must call (do not reimplement): passwordResetRequestSchema,
 * passwordResetConfirmSchema, consumeRateLimit
 */

import { RateLimitedError } from "@/actions/_lib/action-errors";
import { ANONYMOUS_ORG_ID } from "@/actions/_lib/permission-resources";
import { toActionResult } from "@/lib/errors";
import { consumeRateLimit } from "@/lib/rate-limit";
import {
  passwordResetConfirmSchema,
  passwordResetRequestSchema,
} from "@/schemas/auth";
import {
  confirmPasswordReset,
  requestPasswordReset,
} from "@/server/services/auth-service";
import type { ActionResult } from "@/types/api";

const RESET_BUCKET = "auth:password-reset";

export async function requestPasswordResetAction(
  raw: unknown,
): Promise<ActionResult<null>> {
  const parsed = passwordResetRequestSchema.safeParse(raw);
  if (!parsed.success) {
    return toActionResult(parsed.error);
  }

  try {
    const verdict = await consumeRateLimit(ANONYMOUS_ORG_ID, RESET_BUCKET);
    if (!verdict.allowed) {
      throw new RateLimitedError(RESET_BUCKET, verdict.resetAt);
    }

    await requestPasswordReset(parsed.data);
    return { ok: true, data: null, submittedAt: new Date().toISOString() };
  } catch (error) {
    return toActionResult(error);
  }
}

export async function confirmPasswordResetAction(
  raw: unknown,
): Promise<ActionResult<null>> {
  const parsed = passwordResetConfirmSchema.safeParse(raw);
  if (!parsed.success) {
    return toActionResult(parsed.error);
  }

  try {
    const verdict = await consumeRateLimit(ANONYMOUS_ORG_ID, RESET_BUCKET);
    if (!verdict.allowed) {
      throw new RateLimitedError(RESET_BUCKET, verdict.resetAt);
    }

    await confirmPasswordReset(parsed.data);
    return { ok: true, data: null, submittedAt: new Date().toISOString() };
  } catch (error) {
    return toActionResult(error);
  }
}

